187:    FArray4D(size_t ni, size_t nj, size_t nk, size_t nl, int start_i=1, int start_j=1, int start_k=1, int start_l=1)
191:    FArray4D(T* fortranArray, size_t ni, size_t nj, size_t nk, int start_i=1, int start_j=1, int start_k=1, int start_l=1)
195:    ~FArray4D() {

176	class FArray4D {
177	
178	  private:
179	    bool ownsData;
180	    int start_i, start_j, start_k, start_l;
181	
182	  public:
183	    size_t ni, nj, nk, nl;
184	    T* data;
185	
186	    // Constructor to allocate memory
187	    FArray4D(size_t ni, size_t nj, size_t nk, size_t nl, int start_i=1, int start_j=1, int start_k=1, int start_l=1)
188	        : ni(ni), nj(nj), nk(nk), nl(nl), start_i(start_i), start_j(start_j), start_k(start_k), start_l(start_l), data(new T[ni*nj*nk*nl]), ownsData(true) {}
189	
190	    // Constructor to use existing Fortran array
191	    FArray4D(T* fortranArray, size_t ni, size_t nj, size_t nk, int start_i=1, int start_j=1, int start_k=1, int start_l=1)
192	        : ni(ni), nj(nj), nk(nk), nl(nl), start_i(start_i), start_j(start_j), start_k(start_k), start_l(start_l), data(fortranArray), ownsData(false) {}
193	
194	    // Destructor to free memory
195	    ~FArray4D() {
196	        if (data != nullptr && ownsData) {
197	            delete[] data;
198	        }
199	    }
200	
201	    // Access operator
202	    T& operator()(size_t i, size_t j, size_t k, size_t l) {
203	        return data[i-start_i + ni*(j-start_j+nj*(k-start_k+nk*(l-start_l)))];
204	    }
205	
206	    // Const access operator
207	    const T& operator()(size_t i, size_t j, size_t k, size_t l) const {
208	        return data[i-start_i + ni*(j-start_j+nj*(k-start_k+nk*(l-start_l)))];
209	    }
210	
211	    // Method to attach an existing Fortran array
212	    void attach(T* fortranArray) {
213	        data = fortranArray;
214	        ownsData = false;
215	    }
216	};
